from django.db.models import Count, Prefetch


class AuthorViewSet(viewsets.ReadOnlyModelViewSet):
    serializer_class = AuthorSerializer

    def get_queryset(self):
        return (
            Author.objects
            .annotate(books_count=Count("books", distinct=True))
            .prefetch_related(
                Prefetch(
                    "books",
                    queryset=Book.objects.filter(is_active=True).only("id", "title", "author_id"),
                    to_attr="active_books",
                )
            )
        )


class AuthorSerializer(serializers.ModelSerializer):
    books_count = serializers.IntegerField(read_only=True)
    books = serializers.SerializerMethodField()

    class Meta:
        model = Author
        fields = ["id", "full_name", "books_count", "books"]

    def get_books(self, obj):
        return [{"id": b.id, "title": b.title} for b in obj.active_books]
